import socket, base64, os, json, struct, urllib.request, sys

def get_ws_url():
    d = json.load(urllib.request.urlopen("http://127.0.0.1:9222/json/list"))
    for t in d:
        if t.get("type")=="page" and "formcraft" in t.get("url",""):
            return t["webSocketDebuggerUrl"]
    raise SystemExit("no target")

class WS:
    def __init__(self, url):
        assert url.startswith("ws://")
        rest = url[5:]
        hostport, path = rest.split("/",1)
        path = "/"+path
        host, port = hostport.split(":")
        self.s = socket.create_connection((host,int(port)), timeout=15)
        key = base64.b64encode(os.urandom(16)).decode()
        req = ("GET %s HTTP/1.1\\r\\nHost: %s\\r\\nUpgrade: websocket\\r\\nConnection: Upgrade\\r\\n"
               "Sec-WebSocket-Key: %s\\r\\nSec-WebSocket-Version: 13\\r\\n\\r\\n") % (path, hostport, key)
        self.s.sendall(req.encode())
        buf=b""
        while b"\\r\\n\\r\\n" not in buf:
            buf += self.s.recv(4096)
        self.buf = buf.split(b"\\r\\n\\r\\n",1)[1]
    def _read(self, n):
        while len(self.buf) < n:
            d = self.s.recv(65536)
            if not d: raise EOFError
            self.buf += d
        out, self.buf = self.buf[:n], self.buf[n:]
        return out
    def send(self, obj):
        payload = json.dumps(obj).encode()
        hdr = bytearray([0x81])
        n = len(payload)
        if n < 126: hdr.append(0x80 | n)
        elif n < 65536: hdr.append(0x80|126); hdr += struct.pack(">H", n)
        else: hdr.append(0x80|127); hdr += struct.pack(">Q", n)
        mask = os.urandom(4); hdr += mask
        masked = bytes(b ^ mask[i%4] for i,b in enumerate(payload))
        self.s.sendall(bytes(hdr)+masked)
    def recv(self):
        while True:
            b0, b1 = self._read(2)
            op = b0 & 0x0f
            ln = b1 & 0x7f
            if ln == 126: ln = struct.unpack(">H", self._read(2))[0]
            elif ln == 127: ln = struct.unpack(">Q", self._read(8))[0]
            data = self._read(ln)
            if op == 1: return json.loads(data.decode())
            if op == 8: raise EOFError

def evaluate(expr):
    w = WS(get_ws_url())
    w.send({"id":1,"method":"Runtime.evaluate","params":{"expression":expr,"returnByValue":True,"awaitPromise":True}})
    while True:
        m = w.recv()
        if m.get("id")==1:
            return m

if __name__ == "__main__":
    expr = sys.stdin.read()
    r = evaluate(expr)
    res = r.get("result",{}).get("result",{})
    print(json.dumps(res.get("value", res), indent=1)[:6000])
`;
